package com.asmj.marketplace.advertising;
import java.time.*; import java.util.*; import org.springframework.stereotype.Service; import org.springframework.scheduling.annotation.Scheduled;
@Service public class AdvertisingService {
 private final AdCampaignRepository campaigns; private final AdPlacementRepository placements; private final AdPackageRepository packages; private final AdvertisingSettingsRepository settings;
 public AdvertisingService(AdCampaignRepository c,AdPlacementRepository p,AdPackageRepository a,AdvertisingSettingsRepository s){campaigns=c;placements=p;packages=a;settings=s;}
 public void ensureDefaults(){
  if(settings.findById("default").isEmpty())settings.save(new AdvertisingSettings());
  if(placements.count()==0){String[][] rows={{"HOME_HERO","Homepage hero banner","Large homepage banner","1200 × 360 px","720 × 560 px","2"},{"HOME_CARD","Homepage promotional card","Cards between homepage sections","600 × 400 px","600 × 500 px","4"},{"CATEGORY_BANNER","Category banner","Category-specific promotional banner","1200 × 240 px","720 × 360 px","2"},{"SEARCH_SPONSORED","Search sponsored products","Sponsored product cards in search results","Product image","Product image","4"},{"PRODUCT_DETAIL","Product detail promotion","Related vendor promotion on product pages","600 × 300 px","600 × 360 px","2"},{"CART_BANNER","Cart promotional banner","Small promotion below cart items","900 × 180 px","720 × 240 px","1"}};
   for(String[] x:rows){AdPlacement p=new AdPlacement();p.setCode(x[0]);p.setName(x[1]);p.setDescription(x[2]);p.setDesktopSize(x[3]);p.setMobileSize(x[4]);p.setMaxConcurrent(Integer.parseInt(x[5]));placements.save(p);}}
  if(packages.count()==0){String[][] rates={{"HOME_HERO","7","999"},{"HOME_HERO","15","1799"},{"HOME_HERO","30","3499"},{"HOME_CARD","7","499"},{"HOME_CARD","15","899"},{"HOME_CARD","30","1699"},{"CATEGORY_BANNER","7","499"},{"CATEGORY_BANNER","15","899"},{"CATEGORY_BANNER","30","1699"},{"SEARCH_SPONSORED","7","399"},{"SEARCH_SPONSORED","15","699"},{"SEARCH_SPONSORED","30","1299"},{"PRODUCT_DETAIL","7","299"},{"PRODUCT_DETAIL","15","499"},{"PRODUCT_DETAIL","30","999"},{"CART_BANNER","7","199"},{"CART_BANNER","15","349"},{"CART_BANNER","30","699"}};
   for(String[] x:rates){AdPackage a=new AdPackage();a.setPlacementCode(x[0]);a.setName(x[1]+" days");a.setDurationDays(Integer.parseInt(x[1]));a.setPrice(new java.math.BigDecimal(x[2]));packages.save(a);}}
 }
 public AdvertisingSettings currentSettings(){return settings.findById("default").orElseGet(()->{AdvertisingSettings s=new AdvertisingSettings();return settings.save(s);});}
 public List<AdCampaign> live(String code,String categoryId){LocalDate today=LocalDate.now(ZoneId.of("Asia/Kolkata"));return campaigns.findAll().stream().filter(c->code.equals(c.getPlacementCode())&&"VERIFIED".equals(c.getPaymentStatus())&&"APPROVED".equals(c.getApprovalStatus())&&"APPROVED".equals(c.getStatus())&&c.getStartDate()!=null&&c.getEndDate()!=null&&!today.isBefore(c.getStartDate())&&!today.isAfter(c.getEndDate())).filter(c->categoryId==null||categoryId.isBlank()||c.getCategoryId()==null||c.getCategoryId().isBlank()||categoryId.equals(c.getCategoryId())).sorted(Comparator.comparing(AdCampaign::getCreatedAt)).limit(8).toList();}
 public List<AdCampaign> allLive(){return allLive(null,null);}
 public List<AdCampaign> allLive(String targetPin,String categoryId){LocalDate today=LocalDate.now(ZoneId.of("Asia/Kolkata"));long day=today.toEpochDay();List<AdCampaign> eligible=campaigns.findByPaymentStatusAndApprovalStatusAndStatus("VERIFIED","APPROVED","APPROVED").stream().filter(c->c.getStartDate()!=null&&c.getEndDate()!=null&&!today.isBefore(c.getStartDate())&&!today.isAfter(c.getEndDate())).filter(c->c.getTargetPinCodes()==null||c.getTargetPinCodes().isEmpty()||(targetPin!=null&&c.getTargetPinCodes().contains(targetPin))).filter(c->!"CATEGORY_BANNER".equals(c.getPlacementCode())||categoryId==null||categoryId.isBlank()||c.getCategoryId()==null||c.getCategoryId().isBlank()||categoryId.equals(c.getCategoryId())).toList();List<AdCampaign> result=new ArrayList<>();for(AdPlacement placement:placements.findByEnabledTrueOrderByNameAsc()){List<AdCampaign> group=new ArrayList<>(eligible.stream().filter(c->placement.getCode().equals(c.getPlacementCode())).sorted(Comparator.comparing(AdCampaign::getCreatedAt)).toList());if(group.isEmpty())continue;int shift=(int)Math.floorMod(day,group.size());Collections.rotate(group,-shift);result.addAll(group.subList(0,Math.min(placement.getMaxConcurrent(),group.size())));}return result;}
 @Scheduled(cron="0 5 0 * * *",zone="Asia/Kolkata") public void expireCampaigns(){LocalDate today=LocalDate.now(ZoneId.of("Asia/Kolkata"));for(AdCampaign c:campaigns.findAll()){if(c.getEndDate()!=null&&c.getEndDate().isBefore(today)&&!List.of("REJECTED","SUSPENDED","EXPIRED").contains(c.getStatus())){c.setStatus("EXPIRED");c.setUpdatedAt(Instant.now());campaigns.save(c);}}}
}
